export const SUPPORTED_LOCALES = ["en", "ko", "ja", "es", "pt-BR", "zh-CN", "de", "fr"] as const;

export type Locale = (typeof SUPPORTED_LOCALES)[number];
type TranslationKey = keyof typeof translations.en;

let _overrideLocale: Locale | null = null;

function detectLocale(): Locale {
  try {
    const lang = chrome?.i18n?.getUILanguage?.() ?? navigator.language;
    if (lang.startsWith("ko")) return "ko";
    if (lang.startsWith("ja")) return "ja";
    if (lang.startsWith("es")) return "es";
    if (lang.startsWith("pt")) return "pt-BR";
    if (lang.startsWith("zh")) return "zh-CN";
    if (lang.startsWith("de")) return "de";
    if (lang.startsWith("fr")) return "fr";
    return "en";
  } catch {
    return "en";
  }
}

export function getCurrentLocale(): Locale {
  return _overrideLocale ?? detectLocale();
}

export function setLocale(locale: Locale): void {
  _overrideLocale = locale;
}

export function t(key: TranslationKey): string {
  const locale = getCurrentLocale();
  const table = translations[locale] as Record<string, string>;
  const fallback = translations.en as Record<string, string>;
  return table?.[key] ?? fallback[key];
}

export type { TranslationKey };
